    input.dueBefore === undefined
      ? undefined
      : dueBeforePredicate(input.dueBefore),
    input.query === undefined
      ? undefined
      : or(
          like(issues.title, `%${input.query}%`),
          like(issues.description, `%${input.query}%`),
        ),
    // All-of: one membership test per label, so an issue must carry each one.
    ...[...new Set(input.labelIds ?? [])].map((labelId) =>
      inArray(
        issues.id,
        getDb()
          .select({ id: issueLabels.issueId })
          .from(issueLabels)
          .where(
            and(
              orgPredicate(issueLabels.orgId, input.orgId),
              eq(issueLabels.labelId, labelId),
            ),
          ),
      ),
    ),
  );
}

